export const getBatchWireProviderRoutesUrl = (providerId: string) => {
  return `/api/staff/v1/gateway/providers/${providerId}/routes/batch`;
};

/**
 * The "models served" section of a provider's detail page is whole-set editing: ticking
 * something not yet configured creates it, unticking deletes it. This endpoint is where
 * that save lands.
 *
 * The response is an array of per-row results, not all-or-nothing. Granularity is decided
 * by the shape of the response, not by whether the request carries one item or many.
 *
 * This is deliberately not a whole-set PUT. Each row carries several editable attributes
 * plus cascade probe records, so it is not a pure association table and replacement semantics
 * do not hold; what is sent instead is an explicit list of creations and deletions.
 *
 * Creations happen before deletions, inside a single transaction. The two orders fail
 * asymmetrically: deleting first and then failing to create can leave a model with no route
 * at all, a hard outage; creating first and then failing to delete leaves an old alias alive
 * a while longer, with the router splitting some traffic to it by priority and weight.
 * Partly wrong beats wholly wrong. Left to the order of a loop on the client, closing a tab
 * is enough to break it.
 *
 * A failing row does not take successful ones down with it: each row runs on its own
 * savepoint, and a failure rolls back only that row. The successful rows commit together.
 *
 * A creation that hits a unique constraint and a deletion that finds nothing are both
 * reported as `already` rather than `failed`: the database is already in the desired state,
 * and counting that as failure invites repeated retries against a goal already met.
 * Callers should still surface them separately, because they mean the list in hand is
 * stale — possibly because someone else is editing at the same time.
 *
 * The request as a whole returns 200 with the per-row verdicts in the body, for the same
 * reason as the discovery and connectivity endpoints: a caller should not have to work out
 * the HTTP-level outcome before it can read the result.
 * @summary Submit this provider's whole served-model set at once, creating and deleting in one call
 */
export const batchWireProviderRoutes = async (
  providerId: string,
  gatewayRouteBatchInput: GatewayRouteBatchInput,
  options?: RequestInit,
): Promise<GatewayRouteBatchResult> => {
  return customFetch<GatewayRouteBatchResult>(getBatchWireProviderRoutesUrl(providerId), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(gatewayRouteBatchInput),
  });
};

