/**
 * Saving takes effect immediately. There is no multi-step machine of draft, preview,
 * publication and activation — it is one step, and versions, publications and scheduled
 * activation were removed along with it.
 *
 * What still holds:
 * - NULL is not 0. All four paid fields must be present; 0 is a valid value meaning that
 *   billing component is free, and a missing field is rejected. A model being free as a
 *   whole is expressed only by its billing mode, never by setting all four to zero.
 * - A reason is required and is written to the audit log. The publication record used to
 *   carry who changed it, when and why; without it those belong to the audit log — which is
 *   also the only source of the previous value when rolling back.
 * - Risks are still computed. A blocker is rejected outright with 422; a warning — going
 *   below cost, a steep drop in the customer price, affecting several organizations, switching to
 *   free — requires the corresponding code in `acknowledged_risks`, and is otherwise
 *   rejected too. Selling at a loss is a legitimate decision, but it has to be an informed
 *   one. The criteria are unchanged; they simply moved from a separate preview dialog into
 *   the save itself.
 * - The ETag prevents concurrent overwrites. It guards against two people editing at once
 *   and has nothing to do with versioning.
 * @summary Save a model's price; saving takes effect immediately
 */
export const saveGatewayModelPricing = async (
  modelId: string,
  modelPricingInput: ModelPricingInput,
  options?: RequestInit,
): Promise<ModelPricingResource> => {
  return customFetch<ModelPricingResource>(getSaveGatewayModelPricingUrl(modelId), {
    ...options,
    method: "PUT",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(modelPricingInput),
  });
};

