export const getListGatewayModelsUrl = (params?: ListGatewayModelsParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : String(value));
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/staff/v1/gateway/models?${stringifiedParams}`
    : `/api/staff/v1/gateway/models`;
};

/**
 * **Searchable, not paginated.** Capped at 500 rows ordered by slug.
 *
 * Two obstacles stood in front of the cursor. ADR-0187 named the first and
 * ADR-0189 removed it: four whole-set editors read this list, and they need
 * "everything already configured stays visible and stays ticked"
 * (ADR-0086). They no longer depend on it — each now takes its configured
 * set from its own endpoint and its candidates from `q`.
 *
 * The second obstacle is still here, and it is why the cap remains. The
 * catalogue screen filters on **five orthogonal axes** — search, protocol,
 * status, pricing state and routing state — and only search runs in the
 * database. Paginate now and the other four would filter *the page*: asking
 * for unpriced models would answer "the unpriced ones among the first 50",
 * which is wrong with no outward sign.
 *
 * Moving them server-side is not symmetrical work: pricing state is
 * assembled per row by the handler, from a different aggregate. That is the
 * next piece, and the cursor comes after it.
 * @summary The model catalog, including pricing and the union of route capabilities
 */
export const listGatewayModels = async (
  params?: ListGatewayModelsParams,
  options?: RequestInit,
): Promise<ListGatewayModels200> => {
  return customFetch<ListGatewayModels200>(getListGatewayModelsUrl(params), {
    ...options,
    method: "GET",
  });
};

